using System;using System.IO;using System.Drawing;using System.Collections.Generic;using System.Web.Script.Serialization;using System.Windows.Forms;
class CgSubtitleChecks {
 [STAThread]static void Main(){int count=0;var json=new JavaScriptSerializer();foreach(var size in new[]{new Size(800,500),new Size(1280,780),new Size(1920,1080)}){var l=new SubtitleLayout(size.Width,size.Height);foreach(var path in Directory.GetFiles(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"chapters/audio"),"cg.json",SearchOption.AllDirectories)){var entries=json.Deserialize<Dictionary<string,ChapterOneCg>>(File.ReadAllText(path));foreach(var c in entries.Values){if(c.en==null&&c.zh==null)continue;int width=size.Width-l.Inset*2;using(var font=l.Fit(c.en,true,width,l.English)){if(8+SubtitleLayout.EnglishLines(c.en,font,width-22)*(int)Math.Ceiling(font.Height*1.55)>l.English)throw new Exception("CG English clipping");}using(var font=l.Fit(c.zh,false,width,l.Chinese)){if(TextRenderer.MeasureText(c.zh??"",font,new Size(width-5,int.MaxValue),TextFormatFlags.NoPadding|TextFormatFlags.WordBreak).Height+4>l.Chinese)throw new Exception("CG Chinese clipping");}using(var image=new Bitmap(size.Width,size.Height))using(var g=Graphics.FromImage(image))SubtitleLayout.Draw(g,size,c.en,c.zh);count++;}}}Console.WriteLine("PASS "+count+" CG bilingual layouts use shared fixed subtitle geometry and fit bounds");}
}
